import starlight from '@astrojs/starlight';
import { defineConfig } from 'astro/config';
import { createStarlightTypeDocPlugin } from 'starlight-typedoc';

// API reference generated by TypeDoc from each package's public entry points,
// one instance per package. typedoc/entries/ re-exports each entry point under
// its import specifier, and typedoc/tsconfig.json maps @noctcore/auth to its
// sources, so the site builds without building the packages first. The output
// is written to src/content/docs/reference/api/ at build time and gitignored.
const [authTypeDoc, authApiGroup] = createStarlightTypeDocPlugin();
const [redisTypeDoc, redisApiGroup] = createStarlightTypeDocPlugin();
const [prismaTypeDoc, prismaApiGroup] = createStarlightTypeDocPlugin();
const [nestTypeDoc, nestApiGroup] = createStarlightTypeDocPlugin();
const [trpcTypeDoc, trpcApiGroup] = createStarlightTypeDocPlugin();
const typeDocTsconfig = './typedoc/tsconfig.json';
const typeDoc = (name) => ({
  name,
  excludePrivate: true,
  excludeInternal: true,
  readme: 'none',
  // Module pages named README.md are dropped by the plugin when no readme is
  // configured, while the package page still links to them; index.md is kept.
  entryFileName: 'index',
  sort: ['kind', 'alphabetical'],
  // Source links are left out: TypeDoc could not resolve repo-relative paths
  // through the entry re-exports, and a bare file name helps nobody.
  disableSources: true,
});

// Project Pages for github.com/noctcore/auth serve from
// https://noctcore.github.io/auth/. A wrong `base` still builds green and 404s
// every asset, which is why scripts/check-build.ts reads the emitted HTML.
export default defineConfig({
  site: 'https://noctcore.github.io',
  base: '/auth',
  trailingSlash: 'always',
  integrations: [
    starlight({
      title: '@noctcore/auth',
      logo: {
        light: './src/assets/brand/logo-light.svg',
        dark: './src/assets/brand/logo-dark.svg',
        replacesTitle: true,
      },
      customCss: [
        './src/styles/tokens.css',
        './src/styles/theme.css',
        './src/styles/landing.css',
        './src/styles/motion.css',
      ],
      components: { Hero: './src/components/Hero.astro' },
      expressiveCode: {
        themes: ['github-dark-default', 'github-light'],
        // Long install commands wrap instead of hiding their tail behind a scrollbar.
        defaultProps: { overridesByLang: { 'sh,bash,shell': { wrap: true } } },
        styleOverrides: {
          borderRadius: 'var(--nc-radius)',
          borderColor: 'var(--nc-line-soft)',
          codeBackground: 'var(--nc-code-bg)',
          codeFontFamily: 'var(--nc-font-mono)',
          uiFontFamily: 'var(--nc-font)',
          frames: {
            editorBackground: 'var(--nc-code-bg)',
            editorTabBarBackground: 'var(--nc-bg-raised)',
            editorActiveTabBackground: 'var(--nc-code-bg)',
            editorActiveTabIndicatorTopColor: 'var(--nc-accent)',
            editorActiveTabIndicatorBottomColor: 'transparent',
            editorTabBarBorderBottomColor: 'var(--nc-line-soft)',
            terminalBackground: 'var(--nc-code-bg)',
            terminalTitlebarBackground: 'var(--nc-bg-raised)',
            terminalTitlebarBorderBottomColor: 'var(--nc-line-soft)',
            frameBoxShadowCssValue: 'none',
          },
        },
      },
      description: 'A small, readable auth library: every module is tied to the attack it stops.',
      social: [{ icon: 'github', label: 'GitHub', href: 'https://github.com/noctcore/auth' }],
      plugins: [
        authTypeDoc({
          entryPoints: [
            './typedoc/entries/auth.ts',
            './typedoc/entries/argon2.ts',
            './typedoc/entries/testing.ts',
          ],
          tsconfig: typeDocTsconfig,
          output: 'reference/api/auth',
          sidebar: { label: '@noctcore/auth', collapsed: true },
          typeDoc: typeDoc('@noctcore/auth'),
        }),
        redisTypeDoc({
          entryPoints: ['./typedoc/entries/auth-redis.ts'],
          tsconfig: typeDocTsconfig,
          output: 'reference/api/auth-redis',
          sidebar: { label: '@noctcore/auth-redis', collapsed: true },
          typeDoc: typeDoc('@noctcore/auth-redis'),
        }),
        prismaTypeDoc({
          entryPoints: ['./typedoc/entries/auth-prisma.ts'],
          tsconfig: typeDocTsconfig,
          output: 'reference/api/auth-prisma',
          sidebar: { label: '@noctcore/auth-prisma', collapsed: true },
          typeDoc: typeDoc('@noctcore/auth-prisma'),
        }),
        nestTypeDoc({
          entryPoints: ['./typedoc/entries/auth-nestjs.ts'],
          tsconfig: typeDocTsconfig,
          output: 'reference/api/auth-nestjs',
          sidebar: { label: '@noctcore/auth-nestjs', collapsed: true },
          typeDoc: typeDoc('@noctcore/auth-nestjs'),
        }),
        trpcTypeDoc({
          entryPoints: ['./typedoc/entries/auth-trpc.ts'],
          tsconfig: typeDocTsconfig,
          output: 'reference/api/auth-trpc',
          sidebar: { label: '@noctcore/auth-trpc', collapsed: true },
          typeDoc: typeDoc('@noctcore/auth-trpc'),
        }),
      ],
      editLink: { baseUrl: 'https://github.com/noctcore/auth/edit/main/site/' },
      sidebar: [
        { label: 'Overview', link: '/' },
        { label: 'Getting started', link: '/start/getting-started/' },
        {
          label: 'Learn',
          items: [
            { label: 'Topics', link: '/learn/' },
            { label: 'Design choices', link: '/learn/design-choices/' },
            { label: 'Sessions and expiry', link: '/learn/sessions-and-expiry/' },
            { label: 'Revocation races and the epoch fence', link: '/learn/revocation-races/' },
            { label: 'Passwords', link: '/learn/passwords/' },
            { label: 'Enumeration', link: '/learn/enumeration/' },
            { label: 'Brute force and lockout', link: '/learn/brute-force-and-lockout/' },
            { label: 'Email verification', link: '/learn/email-verification/' },
            { label: 'Password reset', link: '/learn/password-reset/' },
            { label: 'CSRF', link: '/learn/csrf/' },
          ],
        },
        {
          label: 'Build',
          items: [
            { label: 'Guides', link: '/build/' },
            { label: 'A Node server with Redis and Prisma', link: '/build/node-server/' },
            { label: 'Mail into your templates and queue', link: '/build/mail/' },
            { label: 'Use with NestJS', link: '/build/nestjs/' },
            { label: 'Use with tRPC', link: '/build/trpc/' },
            { label: 'Writing a store adapter', link: '/build/store-adapter/' },
          ],
        },
        {
          label: 'Reference',
          items: [
            { label: 'Reference', link: '/reference/' },
            { label: 'Configuration', link: '/reference/configuration/' },
            authApiGroup,
            redisApiGroup,
            prismaApiGroup,
            nestApiGroup,
            trpcApiGroup,
          ],
        },
        {
          label: 'Security',
          items: [
            { label: 'Security defaults', link: '/security/' },
            { label: 'Threat model', link: '/security/threat-model/' },
            { label: 'How this library is tested', link: '/security/testing/' },
          ],
        },
      ],
    }),
  ],
  vite: {
    // Starlight renders some Markdown through Satteri, whose native binding is an
    // optional dependency that Bun's isolated linker keeps next to `satteri` only.
    // Leave it external in Astro 7's prerender environment.
    environments: { prerender: { resolve: { external: ['satteri'] } } },
  },
});
